// Read-only copy of firebase/firestore.rules for the D1 cutover write freeze
// (phase 6 of docs/superpowers/plans/2026-10-30-firestore-to-d1-migration.md):
// every read rule stays as it is, every write rule becomes `if false`.

const READ_OPS = new Set(['get', 'list', 'read'])
const WRITE_OPS = new Set(['create', 'update', 'delete', 'write'])

export const FROZEN_RULES_HEADER =
  '// GENERATED by `pnpm rules:generate-frozen` from firebase/firestore.rules: do not edit.\n' +
  '// Deployed during the D1 cutover write freeze (`pnpm rules:freeze`); every write is denied.\n'

/** Index just past the quoted string or comment starting at `i`, or `i` when there is none. */
function skipStringOrComment(source: string, i: number): number {
  const char = source[i]
  if (char === '/' && source[i + 1] === '/') {
    const end = source.indexOf('\n', i)
    return end === -1 ? source.length : end
  }
  if (char === '/' && source[i + 1] === '*') {
    const end = source.indexOf('*/', i + 2)
    if (end === -1) throw new Error('Unterminated comment in rules')
    return end + 2
  }
  if (char === "'" || char === '"') {
    let j = i + 1
    while (j < source.length && source[j] !== char) {
      j += source[j] === '\\' ? 2 : 1
    }
    if (j >= source.length) throw new Error('Unterminated string in rules')
    return j + 1
  }
  return i
}

/** Index of the `;` that ends the statement starting at `i` (strings and comments skipped). */
function statementEnd(source: string, i: number): number {
  let j = i
  while (j < source.length) {
    const skipped = skipStringOrComment(source, j)
    if (skipped !== j) {
      j = skipped
      continue
    }
    if (source[j] === ';') return j
    // A missing `;` would otherwise swallow the next rules up to the next one.
    if (source[j] === '{' || source[j] === '}') {
      throw new Error('allow statement without a terminating ; in rules')
    }
    j++
  }
  throw new Error('Unterminated allow statement in rules')
}

function isIdentifierChar(char: string | undefined): boolean {
  return char !== undefined && /[A-Za-z0-9_]/.test(char)
}

/**
 * Rewrites Firestore rules so that no write is allowed: each `allow` of write
 * operations gets the condition `false`, `allow` of read operations is kept.
 * Throws on an `allow` that mixes reads and writes (split it in the source).
 */
export function freezeFirestoreRules(rules: string): string {
  let output = ''
  let copiedUpTo = 0
  let i = 0
  while (i < rules.length) {
    const skipped = skipStringOrComment(rules, i)
    if (skipped !== i) {
      i = skipped
      continue
    }
    const startsAllow =
      rules.startsWith('allow', i) && !isIdentifierChar(rules[i - 1]) && !isIdentifierChar(rules[i + 5])
    if (!startsAllow) {
      i++
      continue
    }
    const end = statementEnd(rules, i)
    const statement = rules.slice(i, end)
    const match = /^allow\s+([a-z\s,]+?)\s*(?::|$)/.exec(statement)
    if (!match?.[1]) throw new Error(`Cannot parse rules statement: ${statement}`)
    const ops = match[1].split(',').map((op) => op.trim())
    const unknown = ops.filter((op) => !READ_OPS.has(op) && !WRITE_OPS.has(op))
    if (unknown.length > 0) throw new Error(`Unknown operation in rules: ${unknown.join(', ')}`)
    const writes = ops.filter((op) => WRITE_OPS.has(op))
    if (writes.length > 0 && writes.length < ops.length) {
      throw new Error(`Rules statement mixes reads and writes: allow ${ops.join(', ')}`)
    }
    if (writes.length > 0) {
      output += rules.slice(copiedUpTo, i) + `allow ${ops.join(', ')}: if false`
      copiedUpTo = end
    }
    i = end + 1
  }
  return FROZEN_RULES_HEADER + output + rules.slice(copiedUpTo)
}
